L["Tidal Focus"] = "Enfoque de las mareas"
L["Tidal Mastery"] = "Maestría de las mareas"
L["Totemic Focus"] = "Enfoque totémico"
L["Toughness"] = "Dureza"
L["Tranquil Spirit"] = "Espíritu sosegado"
